<?php
require_once 'auth.php'; require_admin(); header('Content-Type: application/json; charset=utf-8'); $pdo=db(); if(!$pdo){echo json_encode(['categories'=>[],'collections'=>[]]);exit;} $productId=(int)($_GET['product_id']??0);$selected=['category_id'=>0,'collection_id'=>0];if($productId){$q=$pdo->prepare('SELECT category_id,collection_id FROM products WHERE id=?');$q->execute([$productId]);$selected=$q->fetch(PDO::FETCH_ASSOC)?:$selected;} echo json_encode(['categories'=>$pdo->query('SELECT id,name,code FROM categories ORDER BY name')->fetchAll(PDO::FETCH_ASSOC),'collections'=>$pdo->query('SELECT id,name,code FROM collections ORDER BY name')->fetchAll(PDO::FETCH_ASSOC),'selected'=>$selected],JSON_UNESCAPED_UNICODE);
